(function(root,factory){if(typeof module==='object')module.exports=factory();else root.AssetWorkspaceValidation=factory();})(globalThis,function(){
 const clone=x=>JSON.parse(JSON.stringify(x));
 function fieldIssues(f,value,path=f.label||f.key){if(value===undefined||value===null||value==='')return f.required?[path+'缺失']:[];if(f.type==='array'){if(!Array.isArray(value))return [path+'应为数组'];if(f.required&&!value.length)return [path+'至少一条'];return value.flatMap((v,i)=>fieldIssues({...f,type:f.item_type||'object',required:true},v,path+'['+i+']'));}if(f.type==='object'){if(typeof value!=='object'||Array.isArray(value))return [path+'应为对象'];return (f.children||[]).flatMap(c=>fieldIssues(c,value[c.key],path+'.'+(c.label||c.key)));}if(['number','integer'].includes(f.type)&&(!Number.isFinite(value)||(f.type==='integer'&&!Number.isInteger(value))))return [path+'应为'+(f.type==='integer'?'整数':'数值')];if(f.type==='boolean'&&typeof value!=='boolean')return [path+'应为布尔值'];if(['text','file'].includes(f.type)&&typeof value!=='string')return [path+'应为文本'];return [];}
 function issues(a){const gaps=[],x=a.config?.actual||{};if(!a.name?.trim()||!a.source?.trim())gaps.push('填写名称与来源');
  if(a.kind==='dataset'){if(!x.schema?.fields?.length)gaps.push('至少定义一个输入字段');if(!x.samples?.length)gaps.push('至少保存一条样本');const ids=new Set();for(const r of x.samples||[]){if(!r.sample_id||ids.has(r.sample_id))gaps.push('样本编号缺失或重复');ids.add(r.sample_id);if('expected'in r)gaps.push('参考不能保存在执行输入中');for(const f of x.schema?.fields||[]){const bag=f.role==='input'?(r.inputs||{}):f.role==='metadata'?(r.metadata||{}):null;if(bag)gaps.push(...fieldIssues(f,bag[f.key]));}}
  }else if(a.kind==='case'){if(!x.objective?.trim())gaps.push('填写测试目标');if(!(x.manual_steps||[]).some(s=>s.action_text?.trim())&&!x.automation?.selector)gaps.push('补充操作步骤或自动化入口');if(!(x.inline_expected?.steps||[]).some(s=>s.text?.trim())&&!x.metric_versions?.length&&!Object.keys(x.inline_expected||{}).some(k=>k!=='steps'))gaps.push('补充预期结果或指标');}
  else if(a.kind==='reference'&&(!x.dataset_ref||!x.records?.length))gaps.push('补充关联数据集与参考记录');return gaps;
 }
 function references(a,core){const refs=[...(a.config.references||[])],x=a.config.actual||{};if(a.kind==='case'){for(const k of ['dataset_version_id','reference_version_id','executor_version_id','environment_version_id'])if(x[k])refs.push(x[k]);refs.push(...(x.metric_versions||[]));if(x.automation?.program_version)refs.push(x.automation.program_version);for(const r of x.sample_refs||[])refs.push(r.dataset_version_id);}const missing=[...new Set(refs)].filter(r=>{const target=core.find(r);return !target||target.id+'@'+target.version!==r||target.status!=='已发布';}).map(r=>'引用尚未在主平台发布：'+r);for(const r of x.sample_refs||[]){const ds=core.find(r.dataset_version_id);if(ds&&!(ds.contentSet?.members||ds.config?.actual?.samples||[]).some(s=>s.sample_id===r.sample_id))missing.push('样本不属于所选数据版本：'+r.sample_id);}if(a.kind==='reference'){const ds=core.find(x.dataset_ref);for(const r of x.records||[])if(ds&&!(ds.config?.actual?.samples||[]).some(s=>s.sample_id===r.sample_id))missing.push('参考无法匹配样本：'+r.sample_id);}return missing;}
 function validate(a){const errors=issues(a);if(errors.length)throw Error(errors.join('；'));const blank=clone(a);blank.name='';const repeated=clone(a);if(a.kind==='dataset'&&repeated.config.actual.samples.length)repeated.config.actual.samples.push(clone(repeated.config.actual.samples[0]));else repeated.source='';return [{id:'CONTENT-READ',expected:'VALID',actual:issues(a).length?'INVALID':'VALID'},{id:'REQUIRED-MISSING',expected:'INVALID',actual:issues(blank).length?'INVALID':'VALID'},{id:'DUPLICATE-OR-SOURCE',expected:'INVALID',actual:issues(repeated).length?'INVALID':'VALID'}];}
 return {issues,references,validate};
});
